class ToDo:
  def __init__(self):
    self.detyrat = []
  def shto(self, d):
    self.detyrat.append(d)

t = ToDo()
t.shto('Studim')
t.shto('Gjumë')
print(t.detyrat)

class ToDo:
  def __init__(self):
    self.detyrat = ['Studim', 'Gjumë']
  def perfundo(self, d):
    if d in self.detyrat:
      self.detyrat.remove(d)

t = ToDo()
t.perfundo('Studim')
print(t.detyrat)
